          // Perform CRC calculation
          feedback = crc_temp ^ data_in;
          feedback = feedback << 1;
          if (feedback[7]) feedback = feedback ^ 8'h07; // XOR with polynomial
          feedback = feedback << 1;
          if (feedback[7]) feedback = feedback ^ 8'h07;
          feedback = feedback << 1;
          if (feedback[7]) feedback = feedback ^ 8'h07;

          crc_temp = feedback;
          crc_reg <= crc_temp;
          state <= IDLE;
        end

        default: begin
          state <= IDLE;
        end
      endcase
