  localparam IDLE = 3'd0;
  localparam CALC = 3'd1;

  // CRC-8 ATM polynomial: x^8 + x^2 + x + 1 => 0x07
  // Reverse polynomial for CRC calculation: 0x8C

  always @(posedge clk or negedge rst_n) begin
